# Stamps the assembly and plugin metadata with the version from the latest git tag.
# Tags look like "1.2.0" or "v1.2.0"; untagged builds get 0.0.0.

$tag = git -C $PSScriptRoot describe --tags --abbrev=0 2>$null
if (-not $tag) { $tag = "0.0.0" }
$version = $tag.TrimStart("v")
$revision = git -C $PSScriptRoot describe --always --tags

@"
// This file is generated by update-version.ps1

using System.Reflection;

[assembly: AssemblyVersion("$version")]
[assembly: AssemblyInformationalVersion("$revision")]
"@ | Out-File $PSScriptRoot\..\Properties\GitVersion.cs -Encoding utf8

$xml = [xml](Get-Content $PSScriptRoot\..\QuickLook.Plugin.Metadata.Base.config)
$xml.Metadata.Version = "$revision"
$xml.Save("$PSScriptRoot\..\QuickLook.Plugin.Metadata.config")
